static int coolkey_init(sc_card_t *card)
{
        int r;
        unsigned long flags;
        unsigned long ext_flags;
        coolkey_private_data_t * priv;

        SC_FUNC_CALLED(card->ctx, SC_LOG_DEBUG_VERBOSE);

        r = coolkey_initialize(card);
        if (r < 0) {
                LOG_FUNC_RETURN(card->ctx, SC_ERROR_INVALID_CARD);
        }

        card->type = SC_CARD_TYPE_COOLKEY_GENERIC;

        /* set Token Major/minor version */
        flags = SC_ALGORITHM_RSA_RAW;

        _sc_card_add_rsa_alg(card, 1024, flags, 0); /* mandatory */

        ctx = card->ctx;
        LOG_FUNC_CALLED(ctx);

        if (card->lock_count != 0)
                return SC_ERROR_NOT_ALLOWED;
        if (card->ops->finish) {
                int r = card->ops->finish(card);
                if (r)
                        sc_log(ctx, "card driver finish() failed: %s", sc_strerror(r));
        }

        if (card->reader->ops->disconnect) {
                int r = card->reader->ops->disconnect(card->reader);
                if (r)
                        sc_log(ctx, "disconnect() failed: %s", sc_strerror(r));
        }

#ifdef ENABLE_SM
        /* release SM related resources */
        sc_card_sm_unload(card);
#endif

        sc_card_free(card);
        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
